// Lookup by pi check ID
export function getCriterionByPiId(piId: string): CriterionDef | undefined {
  return CRITERIA_REGISTRY.find(c => c.piId === piId);
}

// Lookup by Droid criterion ID
export function getCriterionByDroidId(droidId: string): CriterionDef | undefined {
  return CRITERIA_REGISTRY.find(c => c.droidId === droidId);
}

// Get all agent-only criteria (no pi equivalent)
export function getAgentOnlyCriteria(): CriterionDef[] {
  return CRITERIA_REGISTRY.filter(c => c.piId === null);
}

// Get all pi-mapped criteria
export function getPiMappedCriteria(): CriterionDef[] {
  return CRITERIA_REGISTRY.filter(c => c.piId !== null);
}
